 code=raw[builder].decode('utf8');tail=' + read(A / "DE4_CONFERENCE_NEXT25_02_NAVIGATION_DELTA.json")["changes"]\n';assert code.count(tail)==1;code=code.replace(tail,tail.rstrip('\n')+' + read(A / "NEXT25_READY_PERSISTENT20_03_NAVIGATION_DELTA.json")["changes"]\n')
