 code=code.replace('    pending = [\n','    pending = [\n        ("Next25 Current06 — complete packet ready, unsent", "DAMAGE_CONTROL_25_CONFERENCE_06_PREPARATION.json"),\n        ("Persistent20 — preserved full source procedures", "PERSISTENT_DAMAGE_20_SOURCE_CONVERGENCE_CHECK_01.json"),\n',1)
