 vals=[v for n in ast.walk(ast.parse(code)) if isinstance(n,ast.Dict) for k,v in zip(n.keys,n.values) if isinstance(k,ast.Constant) and k.value=='notebookReview'];assert len(vals)==1;code=code.replace(ast.get_source_segment(code,vals[0]),repr(scope),1);compile(code,str(builder),'exec');builder.write_text(code,encoding='utf8',newline='\n')
 delta.write_bytes(encoded({'recordedAtUtc':now,'changes':[{'before':next({**x['source'],'preservedCopy':x['preservedCopy']['path']} for x in saved if x['source']['path']==p.relative_to(G).as_posix()),'after':info(p)} for p in [start,guide,ledger,builder]],'sourceInformationDeleted':0,'newRuleAdoptions':0,'all75DomainGatesUnchanged':True}))
 current={'id':'ACTIVE-AUTHORING-NEXT25-READY-PERSISTENT20-03','recordedAtUtc':now,'status':scope,'previousCheckpoint':info(prev),'historyPolicy':'All previous evidence remains exact and reachable through the prior checkpoint. This is a current navigation/status overlay, not an approval.','counts':oldcp['counts'],'activeGptReview':oldcp['activeGptReview'],'de4':oldcp['de4'],'next25':{'draft':info(draft),'preparation':info(prep),'archive':read(prep)['archive'],'submitted':False,'adopted':False,'originalVectors':36,'highRankSupplementalVectors':15,'nextWork':'After current DE4 response, submit this prepared06 packet to the same actual Director notebook; do not duplicate older05.'},'persistent20':{'sourceAudit':info(audit),'check':info(A/'PERSISTENT_DAMAGE_20_SOURCE_CONVERGENCE_CHECK_01.json'),'submitted':False,'adopted':False},'lastUsageObservation':{'weeklyUsedPercent':6,'weeklyRemainingPercent':94,'shortWindowReported':False},'usageStop':oldcp['usageStop'],'latestVerifiedGitHubBackup':oldcp['latestVerifiedGitHubBackup'],'coverageLedger':info(ledger),'navigationDelta':info(delta),'preservedNavigation':info(keep/'PRESERVATION_MANIFEST.json'),'newRuleAdoptions':0,'sourceInformationDeleted':0,'runtimeTestsExecuted':0,'wholeGameFlowConfirmed':False,'releaseApproved':False}
 cp.write_bytes(encoded(current));run=subprocess.run([sys.executable,'-X','utf8',str(builder)],capture_output=True,text=True,encoding='utf8');assert run.returncode==0,(run.stdout[-2000:],run.stderr[-2000:]);build=read(buildfile);assert not build['missingLinks'];current['navigation']={'map':info(mapfile),'build':info(buildfile),'existingDistinctLinks':build['existingDistinctLinks'],'missingLinks':[]};cp.write_bytes(encoded(current));report.write_bytes(encoded({'checkpoint':info(cp),'delta':info(delta),'savedNavigationFiles':len(saved),'all75DomainGatesUnchanged':True,'existingDistinctLinks':build['existingDistinctLinks'],'missingLinks':[],'newRuleAdoptions':0,'runtimeTestsExecuted':0,'sourceInformationDeleted':0}));print(json.dumps(read(report)))

